var punctual_default = "struct Light\n{\nvec3 direction;\nfloat range;\nvec3 color;\nfloat intensity;\nvec3 position;\nfloat innerConeCos;\nfloat outerConeCos;\nint type;\n};\nconst int LightType_Directional = 0;\nconst int LightType_Point = 1;\nconst int LightType_Spot = 2;\n#ifdef USE_PUNCTUAL\nuniform Light u_Lights[LIGHT_COUNT + 1];\n#endif\n#ifdef MATERIAL_SCATTER\nuniform vec3 u_ScatterSamples[SCATTER_SAMPLES_COUNT];\nuniform float u_ScatterStrengthFactor;\nuniform float u_ScatterAnisotropy;\nuniform vec3 u_MultiScatterColorFactor;\nuniform float u_MinRadius;\nuniform ivec2 u_FramebufferSize;\n#endif\nfloat getRangeAttenuation(float range, float distance)\n{\nif (range <= 0.0)\n{\nreturn 1.0 / pow(distance, 2.0);\n}\nreturn max(min(1.0 - pow(distance / range, 4.0), 1.0), 0.0) / pow(distance, 2.0);\n}\nfloat getSpotAttenuation(vec3 pointToLight, vec3 spotDirection, float outerConeCos, float innerConeCos)\n{\nfloat actualCos = dot(normalize(spotDirection), normalize(-pointToLight));\nif (actualCos > outerConeCos)\n{\nif (actualCos < innerConeCos)\n{\nfloat angularAttenuation = (actualCos - outerConeCos) / (innerConeCos - outerConeCos);\nreturn angularAttenuation * angularAttenuation;\n}\nreturn 1.0;\n}\nreturn 0.0;\n}\nvec3 getLighIntensity(Light light, vec3 pointToLight)\n{\nfloat rangeAttenuation = 1.0;\nfloat spotAttenuation = 1.0;\nif (light.type != LightType_Directional)\n{\nrangeAttenuation = getRangeAttenuation(light.range, length(pointToLight));\n}\nif (light.type == LightType_Spot)\n{\nspotAttenuation = getSpotAttenuation(pointToLight, light.direction, light.outerConeCos, light.innerConeCos);\n}\nreturn rangeAttenuation * spotAttenuation * light.intensity * light.color;\n}\nvec3 getPunctualRadianceTransmission(vec3 normal, vec3 view, vec3 pointToLight, float alphaRoughness,\nvec3 baseColor, float ior)\n{\nfloat transmissionRougness = applyIorToRoughness(alphaRoughness, ior);\nvec3 n = normalize(normal);\nvec3 v = normalize(view);\nvec3 l = normalize(pointToLight);\nvec3 l_mirror = normalize(l + 2.0*n*dot(-l, n));\nvec3 h = l_mirror + v;\nfloat hLen = length(h);\nh = hLen > 1e-5 ? h / hLen : n;\nfloat D = D_GGX(abs(dot(n, h)), transmissionRougness);\nfloat Vis = V_GGX(abs(dot(n, l_mirror)), abs(dot(n, v)), transmissionRougness);\nreturn baseColor * D * Vis;\n}\nvec3 getPunctualRadianceClearCoat(vec3 clearcoatNormal, vec3 v, vec3 l, vec3 h, float VdotH, vec3 f0, vec3 f90, float clearcoatRoughness)\n{\nfloat NdotL = clampedDot(clearcoatNormal, l);\nfloat NdotV = clampedDot(clearcoatNormal, v);\nfloat NdotH = clampedDot(clearcoatNormal, h);\nreturn NdotL * BRDF_specularGGX(clearcoatRoughness * clearcoatRoughness, NdotL, NdotV, NdotH);\n}\nvec3 getPunctualRadianceSheen(vec3 sheenColor, float sheenRoughness, float NdotL, float NdotV, float NdotH)\n{\nreturn NdotL * BRDF_specularSheen(sheenColor, sheenRoughness, NdotL, NdotV, NdotH);\n}\nvec3 applyVolumeAttenuation(vec3 radiance, float transmissionDistance, vec3 attenuationColor, float attenuationDistance)\n{\nif (attenuationDistance == 0.0)\n{\nreturn radiance;\n}\nelse\n{\nvec3 transmittance = pow(attenuationColor, vec3(transmissionDistance / attenuationDistance));\nreturn transmittance * radiance;\n}\n}\nvec3 getVolumeTransmissionRay(vec3 n, vec3 v, float thickness, float ior, mat4 modelMatrix)\n{\nvec3 refractionVector = refract(-v, normalize(n), 1.0 / ior);\nvec3 modelScale;\nmodelScale.x = length(vec3(modelMatrix[0].xyz));\nmodelScale.y = length(vec3(modelMatrix[1].xyz));\nmodelScale.z = length(vec3(modelMatrix[2].xyz));\nreturn normalize(refractionVector) * thickness * modelScale;\n}\n#ifdef MATERIAL_SCATTER\nfloat getScatterStrength() {\nfloat scatterStrength = u_ScatterStrengthFactor;\n#ifdef HAS_SCATTER_STRENGTH_MAP\nscatterStrength *= texture(u_ScatterStrengthSampler, getScatterStrengthUV()).a;\n#endif\nreturn clamp(scatterStrength, 0.0, 1.0);\n}\nvec3 getMultiScatterColor() {\nvec3 multiscatterColor = u_MultiScatterColorFactor;\n#ifdef HAS_MULTISCATTER_COLOR_MAP\nmultiscatterColor *= texture(u_MultiScatterColorSampler, getMultiScatterColorUV()).rgb;\n#endif\nreturn multiscatterColor;\n}\nvec3 multiToSingleScatter() {\nvec3 rhoMs = getMultiScatterColor() * getScatterStrength();\nvec3 s = 4.09712 + 4.20863 * rhoMs - sqrt(9.59217 + 41.6808 * rhoMs + 17.7126 * rhoMs * rhoMs);\ns = clamp(s, 0.0, 1.0);\nvec3 zeroInput = vec3(equal(rhoMs, vec3(0.0)));\ns = mix(s, vec3(1.0), zeroInput);\nvec3 rhoSs = (1.0 - s * s) / (1.0 - u_ScatterAnisotropy * s * s);\nreturn clamp(rhoSs, 0.0, 1.0);\n}\nvec3 burley_setup(vec3 radius, vec3 albedo) {\nfloat m_1_pi = 0.318309886183790671538;\nvec3 s = 1.9 - albedo + 3.5 * ((albedo - 0.8) * (albedo - 0.8));\nvec3 l = 0.25 * m_1_pi * radius;\nreturn l / s;\n}\nvec3 burley_eval(vec3 d, float r)\n{\nvec3 exp_r_3_d = exp(-r / (3.0 * d));\nvec3 exp_r_d = exp_r_3_d * exp_r_3_d * exp_r_3_d;\nreturn (exp_r_d + exp_r_3_d) / (4.0 * d);\n}\nvec3 getSubsurfaceScattering(vec3 position, mat4 projectionMatrix, float attenuationDistance, sampler2D scatterLUT, vec3 diffuseColor, vec3 singleScatter) {\nvec3 multiScatter = getScatterStrength() * getMultiScatterColor();\nvec3 scatterDistance = attenuationDistance * mix(multiScatter, singleScatter, abs(u_ScatterAnisotropy));\nfloat maxColor = max3(scatterDistance);\nvec3 vMaxColor = max(vec3(maxColor), vec3(0.00001));\nvec2 texelSize = 1.0 / vec2(textureSize(u_ScatterDepthFramebufferSampler, 0));\nmat4 inverseProjectionMatrix = inverse(projectionMatrix);\nvec2 uv = gl_FragCoord.xy * (1.0 / vec2(u_FramebufferSize));\nvec4 centerSample = textureLod(scatterLUT, uv, 0.0);\nfloat centerDepth = textureLod(u_ScatterDepthFramebufferSampler, uv, 0.0).r;\ncenterDepth = centerDepth * 2.0 - 1.0;\nvec2 clipUV = uv * 2.0 - 1.0;\nvec4 clipSpacePosition = vec4(clipUV.x, clipUV.y, centerDepth, 1.0);\nvec4 upos = inverseProjectionMatrix * clipSpacePosition;\nvec3 fragViewPosition = upos.xyz / upos.w;\nupos = inverseProjectionMatrix * vec4(clipUV.x + texelSize.x, clipUV.y, centerDepth, 1.0);\nvec3 offsetViewPosition = upos.xyz / upos.w;\nfloat mPerPixel = distance(fragViewPosition, offsetViewPosition);\nfloat maxRadiusPixels = maxColor / mPerPixel;\nif (maxRadiusPixels <= 1.0) {\nreturn centerSample.rgb * diffuseColor;\n}\ncenterDepth = fragViewPosition.z;\nvec3 totalWeight = vec3(0.0);\nvec3 totalDiffuse = vec3(0.0);\nvec3 clampedScatterDistance = max(vec3(u_MinRadius), scatterDistance / maxColor) * maxColor;\nvec3 d = burley_setup(clampedScatterDistance, vec3(1.0));\nfor (int i = 0; i < SCATTER_SAMPLES_COUNT; i++) {\nvec3 scatterSample = u_ScatterSamples[i];\nfloat fabAngle = scatterSample.x;\nfloat r = scatterSample.y * maxRadiusPixels * texelSize.x;\nfloat rcpPdf = scatterSample.z;\nvec2 sampleCoords = vec2(cos(fabAngle) * r, sin(fabAngle) * r);\nvec2 sampleUV = uv + sampleCoords;\nvec4 textureSample = textureLod(scatterLUT, sampleUV, 0.0);\nif (centerSample.w == textureSample.w) {\nfloat sampleDepth = textureLod(u_ScatterDepthFramebufferSampler, sampleUV, 0.0).r;\nsampleDepth = sampleDepth * 2.0 - 1.0;\nvec2 sampleClipUV = sampleUV * 2.0 - 1.0;\nvec4 sampleUpos = inverseProjectionMatrix * vec4(sampleClipUV.x, sampleClipUV.y, sampleDepth, 1.0);\nvec3 sampleViewPosition = sampleUpos.xyz / sampleUpos.w;\nfloat sampleDistance = distance(sampleViewPosition, fragViewPosition);\nvec3 weight = burley_eval(d, sampleDistance) * rcpPdf;\ntotalWeight += weight;\ntotalDiffuse += weight * textureSample.rgb;\n}\n}\ntotalWeight = max(totalWeight, vec3(0.0001));\nreturn totalDiffuse / totalWeight * diffuseColor;\n}\n#endif";
